-- V6: usuario genérico para compras como invitado.
-- Cuando el front compra sin sesión, envía usuarioId: 2 en la orden.
-- La dirección de despacho NO va a 'direcciones': se guarda como snapshot
-- en la tabla 'ordenes' (calle, numero, complemento, comuna, region).
--
-- El id se fija en 2 para que coincida con el usuario invitado actual de Neon.
-- V1 define usuarios.id como "generated by default as identity", así que se
-- puede insertar con id explícito sin conflicto con la secuencia.
-- Idempotente: si el correo ya existe, no hace nada.
INSERT INTO public.usuarios (id, nombre, email, password, rol, fecha_nacimiento)
VALUES (2, 'Invitado', 'invitado@taberna.cl',
        '$2a$10$0VR4uWctMNsdY3mJU8.Lt.6SuGC7q3Ollq3krAAHfn.TPp0P.5BH.',
        'cliente', NULL)
ON CONFLICT (email) DO NOTHING;
